  function baseCatalogPrice(raw='',fallback=1){const meta=itemMeta(raw),fixed=FAERIE_PRICE_TABLE.find(x=>itemMeta(x.raw||x.name).key===meta.key),custom=ensureEditorCatalog(appState.book).items.map(normalizeCustomItemDefinition).find(x=>itemMeta(x.raw).key===meta.key);return Math.max(1,parseInt(fixed?.price??custom?.price??fallback)||1);}
