  function ensureFaerieMarketState(p=appState.player){if(!p)return null;if(!Number.isFinite(p.faerieMarketVisits))p.faerieMarketVisits=0;if(!Number.isFinite(p.faerieMarketCycle))p.faerieMarketCycle=-1;if(!Array.isArray(p.faerieMarketOffers))p.faerieMarketOffers=[];if(typeof p.faerieLoanUsed!=='boolean')p.faerieLoanUsed=false;if(!Number.isFinite(p.faerieDebt))p.faerieDebt=0;if(!Number.isFinite(p.faerieDebtLastPaymentTurn))p.faerieDebtLastPaymentTurn=Number(p.turnSerial)||0;if(!Number.isFinite(p.faerieStealAttempts))p.faerieStealAttempts=0;p.faerieDebt=Math.max(0,Math.round(Number(p.faerieDebt)||0));return p;}
  function faerieDebtAmount(p=appState.player){return Math.max(0,Math.round(Number(ensureFaerieMarketState(p)?.faerieDebt)||0));}
  function faerieDebtDisplay(){const debt=faerieDebtAmount();return debt?`🪙×-${debt}`:`🪙×${goldCount()}`;}
  function faerieDebtApplyPayment(amount,{silent=false}={}){const p=ensureFaerieMarketState(),n=Math.max(0,Math.round(Number(amount)||0));if(!p||!n||p.faerieDebt<=0)return 0;const paid=Math.min(n,p.faerieDebt);p.faerieDebt=Math.max(0,p.faerieDebt-paid);p.faerieDebtLastPaymentTurn=Number(p.turnSerial)||0;if(!silent)toast(p.faerieDebt?`${paid} ${currencyName()} amortizaram a dívida faérica. Saldo: -${p.faerieDebt}.`:`A dívida com as fadas foi liquidada.`);return paid;}
  function faerieCheapestCollateral(){const candidates=[];for(const entry of inventoryCounts()){const price=adventureItemPrice(entry.meta.raw,1);candidates.push({kind:'item',meta:entry.meta,price:Math.max(1,price)});}if((Number(appState.player?.provisions)||0)>0)candidates.push({kind:'provision',name:'Provisão',price:Math.max(1,adventureItemPrice('Provisão',3))});return candidates.sort((a,b)=>a.price-b.price||String(a.meta?.name||a.name).localeCompare(String(b.meta?.name||b.name),'pt-BR'))[0]||null;}
  async function collectFaerieDebt(){const p=ensureFaerieMarketState();if(!p||p.faerieDebt<=0||appState.faerieDebtCollecting)return false;appState.faerieDebtCollecting=true;try{const collateral=faerieCheapestCollateral();let detail='As fadas vieram cobrar, mas sua bagagem ofereceu pouco interesse.';if(collateral){if(collateral.kind==='provision'){p.provisions=Math.max(0,p.provisions-1);recordJournal('As fadas cobraram 1 provisão da minha dívida.',{kind:'commerce'});markRuntimeChanged();}else{removeOneItem(collateral.meta.raw,{journal:false});recordJournal(`As fadas cobraram ${collateral.meta.name} da minha dívida.`,{kind:'commerce'});}const name=collateral.kind==='provision'?'Provisão':collateral.meta.name,paid=Math.min(p.faerieDebt,collateral.price);p.faerieDebt=Math.max(0,p.faerieDebt-paid);p.faerieDebtLastPaymentTurn=Number(p.turnSerial)||0;detail=`As fadas tomam ${name}, avaliado em ${collateral.price} ${currencyName()}, e abatem ${paid} da dívida.${p.faerieDebt?` Saldo restante: -${p.faerieDebt}.`:' A conta está quitada.'}`;}else p.faerieDebtLastPaymentTurn=Number(p.turnSerial)||0;renderAll();await openFaerieMarket({collection:{detail}});return true;}finally{appState.faerieDebtCollecting=false;}}
  function scheduleFaerieDebtCollection(){const p=ensureFaerieMarketState();if(!p||p.faerieDebt<=0||appState.faerieDebtCollecting)return;const elapsed=(Number(p.turnSerial)||0)-(Number(p.faerieDebtLastPaymentTurn)||0);if(elapsed<10)return;const attempt=()=>{if(appState.faerieDebtCollecting||faerieDebtAmount()<=0)return;const current=ensureFaerieMarketState(),age=(Number(current?.turnSerial)||0)-(Number(current?.faerieDebtLastPaymentTurn)||0);if(age<10)return;const busy=[...document.querySelectorAll('dialog[open]')].some(d=>d.id!=='faerieMarketDialog');if(busy){setTimeout(attempt,420);return;}collectFaerieDebt();};setTimeout(attempt,60);}
  function faerieOfferCopy(item){const base=adventureItemPrice(item.raw||item.name,item.price);return {name:item.name,raw:item.raw,qty:Math.max(1,parseInt(item.qty)||1),type:item.type,basePrice:base,price:base,sold:false,double:false};}
  function generateFaerieOffers(){
    const armDef=faerieOfferCopy(faeriePick(FAERIE_PRICE_TABLE.filter(x=>x.type==='arma'||x.type==='defesa'))),mushroom=faerieOfferCopy(faerieItems('cogumelo')[0]),spell=faerieOfferCopy(faeriePick(faerieItems('feitiço'))),lore=faerieOfferCopy(faeriePick(FAERIE_PRICE_TABLE.filter(x=>x.type==='livro'||x.type==='poção'))),item=faerieOfferCopy(faeriePick(faerieItems('item')));
    const offers=[armDef,spell,lore,item,mushroom],mushroomPrice=Math.ceil(mushroom.basePrice*(1.05+Math.random()*.08));mushroom.price=mushroomPrice;
    const doubleOffer=offers.filter(x=>x!==mushroom).sort((a,b)=>b.basePrice-a.basePrice)[0]||null;
    for(const offer of offers){if(offer===mushroom)continue;if(offer===doubleOffer&&offer.basePrice>=50){offer.price=offer.basePrice*2;offer.double=true;}else offer.price=Math.max(1,Math.ceil(offer.basePrice*(1.05+Math.random()*.16)));}
    return offers.sort(()=>Math.random()-.5);
  }
