  function esc(s=''){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
  function cleanText(s=''){ return String(s).trim(); }
  function openSamsaraDB(){
    if(samsaraDbPromise)return samsaraDbPromise;
    samsaraDbPromise=new Promise((resolve,reject)=>{try{const request=indexedDB.open(SAMSARA_DB_NAME,SAMSARA_DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(SAMSARA_DB_ADVENTURES))db.createObjectStore(SAMSARA_DB_ADVENTURES,{keyPath:'id'});if(!db.objectStoreNames.contains(SAMSARA_DB_SAVES))db.createObjectStore(SAMSARA_DB_SAVES,{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);}catch(err){reject(err);}});return samsaraDbPromise;
  }
  async function idbPut(storeName,value){const db=await openSamsaraDB();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite');tx.objectStore(storeName).put(value);tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);});}
  async function idbGet(storeName,key){const db=await openSamsaraDB();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});}
  async function idbDelete(storeName,key){try{const db=await openSamsaraDB();return await new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite');tx.objectStore(storeName).delete(key);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);});}catch(err){console.warn('[Samsara DB] exclusão indisponível.',err);return false;}}
  async function deleteSamsaraDatabase(){try{if(samsaraDbPromise){const db=await samsaraDbPromise.catch(()=>null);try{db?.close?.();}catch{}samsaraDbPromise=null;}return await new Promise(resolve=>{const req=indexedDB.deleteDatabase(SAMSARA_DB_NAME);req.onsuccess=req.onerror=req.onblocked=()=>resolve(true);});}catch{return false;}}
  async function persistAdventureDefinition(book=appState.book,filename=appState.currentFilename){if(!book)return false;const id=ensureBookIdentity(book);try{await idbPut(SAMSARA_DB_ADVENTURES,{id,format:SAMSARA_FORMAT_ID,filename:filename||'livro-jogo.md',updatedAt:Date.now(),book:deepClone(book)});appState.adventureId=id;return true;}catch(err){console.warn('[Samsara DB] aventura não persistida.',err);return false;}}
