  function scheduleAutosave(){if(!(appState.book&&appState.player&&!appState.editor&&appState.adventureStarted))return;if(autosaveTimer)clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>{autosaveTimer=null;const task=()=>{if(persistedRevision===runtimeRevision)return;saveAdventureToStorage(false);};if('requestIdleCallback'in window)requestIdleCallback(task,{timeout:1500});else setTimeout(task,0);},750);}
