  const renderAreaHandlers={inventory:()=>renderInventory(),save:()=>renderSaveBookmark(),choices:()=>renderChoices(),effects:()=>renderEffects(),combat:()=>renderCombat(),clock:()=>{renderGameClock();renderTimeLighting();},journal:()=>{if(el('journalDialog')?.open)renderJournal();}};
  function invalidateRender(...areas){const list=areas.flat().filter(Boolean);if(!list.length||list.includes('all')){renderPendingAll=true;}else{if(!invalidateRender.pending)invalidateRender.pending=new Set();for(const area of list)invalidateRender.pending.add(area);}if(renderFrame)return;renderFrame=requestAnimationFrame(()=>{renderFrame=0;const full=renderPendingAll;renderPendingAll=false;const pending=invalidateRender.pending?[...invalidateRender.pending]:[];invalidateRender.pending?.clear?.();if(full)renderAll();else for(const area of pending)try{renderAreaHandlers[area]?.();}catch(err){console.warn(`[Samsara Render] ${area}`,err);}});}

  const JOURNAL_LIMIT=320;
  function ensureJournal(){if(!Array.isArray(appState.journal))appState.journal=[];return appState.journal;}
  function journalClock(minutes=Number(ensureTimeState()?.gameMinutes)||adventureStartMinutes()){const total=Math.max(0,Math.round(Number(minutes)||0)),day=Math.floor(total/1440)+1,clock=formatAdventureClockMinutes(total);return {minutes:total,day,clock,label:`Dia ${day} - ${clock}`};}
  function journalEnabled(){return !!(appState.book&&appState.player&&appState.adventureStarted&&!appState.editor&&!appState.journalMuted);}
  function recordJournal(text,{kind='event',minutes=null,dedupeKey=''}={}){const copy=cleanText(text);if(!copy||!journalEnabled())return null;const time=journalClock(minutes==null?undefined:minutes),journal=ensureJournal(),duplicate=dedupeKey?journal.find(entry=>entry?.dedupeKey===dedupeKey&&entry?.minutes===time.minutes&&entry?.text===copy):null;if(duplicate)return duplicate;const entry={id:`jr-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`,minutes:time.minutes,day:time.day,clock:time.clock,text:copy,kind,dedupeKey};journal.push(entry);if(journal.length>JOURNAL_LIMIT)journal.splice(0,journal.length-JOURNAL_LIMIT);markRuntimeChanged();invalidateRender('journal');return entry;}
  function journalItemLabel(item,qty=1){const meta=itemMeta(item),name=isProvisionName(item)?'Provisão':isGoldItem(item)?currencyName():meta.name;return qtyLabel(Math.max(1,Number(qty)||1),name);}
  function journalRecordItem(item,qty,mode='add',verb=''){const n=Math.max(1,Number(qty)||1),label=journalItemLabel(item,n),action=cleanText(verb)||(mode==='add'?'Adquiri':'Gastei');return recordJournal(`${action} ${label}.`,{kind:'item'});}
  function stateRemainingCopy(entry){const remaining=Number(entry?.turnsRemaining);return Number.isFinite(remaining)?`${entry.name}: ${Math.max(0,remaining)} turno${remaining===1?'':'s'} restante${remaining===1?'':'s'}`:entry?.name||'';}
