  function journalRecordCombatResolution(c){if(!c?.won||c.sanityIllusion)return null;const name=cleanText(c.name)||'o oponente',outcome=c.outcome||(c.fled?'fuga_monstro':'vitoria_heroi'),key=`combat:${appState.sectionId}:${c.id||c.opponentId||name}:${outcome}`;if(outcome==='poupado')return recordJournal(`Poupei ${name}.`,{kind:'combat',dedupeKey:key});if(c.fled||outcome==='fuga_monstro')return recordJournal(`Venci o confronto contra ${name}; o oponente fugiu.`,{kind:'combat',dedupeKey:key});return recordJournal(`Venci ${name} em combate.`,{kind:'combat',dedupeKey:key});}
