  function renderJournal(){const box=el('journalList');if(!box)return;box.innerHTML='';const entries=[...ensureJournal()].reverse();if(!entries.length){const empty=document.createElement('div');empty.className='journal-empty';empty.textContent='Meu diário ainda está em branco.';box.appendChild(empty);return;}const frag=document.createDocumentFragment();for(const entry of entries){const row=document.createElement('article');row.className=`journal-entry kind-${entry.kind||'event'}`;const time=document.createElement('time');time.className='journal-time';time.textContent=`Dia ${Math.max(1,Number(entry.day)||1)} - ${entry.clock||formatAdventureClockMinutes(entry.minutes)}`;time.dateTime=`${String(Math.max(1,Number(entry.day)||1)).padStart(3,'0')}-${entry.clock||'00:00'}`;const copy=document.createElement('div');copy.className='journal-copy';copy.textContent=entry.text;row.append(time,copy);frag.appendChild(row);}box.appendChild(frag);}
