  function firstText(s=''){ return cleanText(s).replace(/^#+\s*/gm,'').replace(/[*_>`~-]/g,'').replace(/\s+/g,' ').slice(0,86)||'Seção sem texto'; }
  function truncateWords(text='',limit=50){const raw=String(text||'').trim(),words=raw.split(/\s+/).filter(Boolean),max=Math.max(1,Math.floor(Number(limit)||50));return words.length>max?`${words.slice(0,max).join(' ')}...`:raw;}
  function normalizeHex(hex){ if(/^#[0-9a-f]{6}$/i.test(hex))return hex;if(/^#[0-9a-f]{3}$/i.test(hex))return '#'+[...hex.slice(1)].map(x=>x+x).join('');return '#6d4aff'; }
  function contrastFor(hex){ hex=normalizeHex(hex).slice(1);const rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4));const lum=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];return lum>.48?'#17161d':'#fff'; }
  function hexToRgb(hex){hex=normalizeHex(hex).slice(1);return [0,2,4].map(i=>parseInt(hex.slice(i,i+2),16));}
  function mixHex(a,b,t){const A=hexToRgb(a),B=hexToRgb(b);const c=A.map((v,i)=>Math.round(v+(B[i]-v)*Math.max(0,Math.min(1,t))));return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join('');}
  function applyTheme(){document.documentElement.style.setProperty('--accent','#6d4aff');document.documentElement.style.setProperty('--accent-ink','#fff');}
  function energyCondition(){
    const p=appState.player;if(!p)return {label:'',skillPenalty:0,ratio:1,overloaded:false,sleepy:false,hungry:false};
    ensureTimeState();
    const ratio=p.initialStamina>0?Math.max(0,Math.min(1,p.stamina/p.initialStamina)):0,pct=ratio*100,overloaded=currentLoad()>=loadLimit();
    const sleepy=survivalEnabled()&&p.awakeMinutes>=sleepyLimitMinutes(p),hungry=survivalEnabled()&&(p.gameMinutes-p.lastMealMinutes)>=hungerLimitMinutes(p);
    let baseLabel='',basePenalty=0;
    if(p.stamina<=0)baseLabel='MORTO';
    else if(p.stamina===2){baseLabel='GRAVEMENTE FERIDO';basePenalty=pct<=25?1:0;}
    else if(pct<=25){baseLabel='FERIDO';basePenalty=1;}
    else if(pct<=40)baseLabel='CANSADO';
    else if(pct<=50)baseLabel='FAMINTO';
    const labels=[baseLabel,overloaded&&p.stamina>0?'SOBRECARREGADO':'',sleepy&&p.stamina>0?'COM SONO':'',hungry&&p.stamina>0?'COM FOME':''].filter(Boolean);
    return {label:labels.join(' · '),labels,skillPenalty:basePenalty+(overloaded&&p.stamina>0?1:0),ratio,overloaded,baseLabel,sleepy,hungry};
  }
  function ensurePlayerStats(){const p=appState.player;if(!p)return null;const initialSkill=Number.isFinite(p.initialSkill)?p.initialSkill:0;if(!Number.isFinite(p.skill))p.skill=initialSkill;if(!Number.isFinite(p.stamina))p.stamina=Number.isFinite(p.initialStamina)?p.initialStamina:0;if(!Number.isFinite(p.luck))p.luck=Number.isFinite(p.initialLuck)?p.initialLuck:0;if(!Number.isFinite(p.initialMagic)&&!Number.isFinite(p.magic)){const rolled=rollStartingMagic(p.classKey,secureDie(),appState.difficulty);p.initialMagic=rolled;p.magic=rolled;}else{if(!Number.isFinite(p.initialMagic))p.initialMagic=Math.max(0,Number(p.magic)||0);if(!Number.isFinite(p.magic))p.magic=Math.max(0,Number(p.initialMagic)||0);}p.initialMagic=Math.max(0,p.initialMagic);if(!Array.isArray(p.exceptionalEvents))p.exceptionalEvents=[];if(!Array.isArray(p.epaAppearance))p.epaAppearance=[];if(!Array.isArray(p.epaReversals))p.epaReversals=[];if(!Number.isFinite(p.turnSerial))p.turnSerial=0;if(p.epaEnvironment===undefined)p.epaEnvironment=null;if(p.epaHazard===undefined)p.epaHazard=null;if(p.epaSquid===undefined)p.epaSquid=null;if(p.lastMagicEffect===undefined)p.lastMagicEffect=null;if(p.epaBaseImage===undefined)p.epaBaseImage='';p.epaMagicPenalty=0;ensureKnowledgeState(p);migrateClassFeaturesToKnowledges(p);p.rulesVersion=Math.max(Number(p.rulesVersion)||0,SAMSARA_RULES_VERSION);return p;}
  function effectiveHeroSkill(){const p=ensurePlayerStats();if(!p)return 0;const energyPenalty=Number(energyCondition().skillPenalty)||0,defensePenalty=Number(armorSkillPenalty())||0,sleepPenalty=survivalEnabled()?(Number(p.sleepSkillPenalty)||0):0;return Math.max(0,p.skill-energyPenalty-defensePenalty-sleepPenalty-epaHeroSkillPenalty());}
  function clampNumber(min,max,value){return Math.max(min,Math.min(max,value));}
  function hungerLimitMinutes(player=appState.player){const energy=Number(player?.initialStamina)||19,hours=Math.round(clampNumber(5,8,6+.25*(energy-19))*2)/2;return hours*60;}
  function sleepyLimitMinutes(player=appState.player){const energy=Number(player?.initialStamina)||19,hours=Math.round(clampNumber(16,22,18+.5*(energy-19)));return hours*60;}
