  function updateVitalTheme(){
    if(!appState.player){document.documentElement.style.setProperty('--vital','#16a34a');document.documentElement.style.setProperty('--hero-life','100%');return;}
    const p=appState.player,ratio=p.initialStamina>0?Math.max(0,Math.min(1,p.stamina/p.initialStamina)):0;
    document.documentElement.style.setProperty('--hero-life',`${(ratio*100).toFixed(2)}%`);
    if(appState.editor){document.documentElement.style.setProperty('--vital','#6d4aff');return;}
    let color;
    if(ratio>=2/3){const t=(ratio-2/3)/(1/3);color=mixHex('#15803d','#22c55e',t);}
    else if(ratio>=1/3){const t=(ratio-1/3)/(1/3);color=mixHex('#eab308','#15803d',t);}
    else{const t=ratio/(1/3);color=mixHex('#dc2626','#eab308',t);}
    document.documentElement.style.setProperty('--vital',color);
  }

