  function migrateClassFeaturesToKnowledges(p=appState.player){if(!p)return;const prior=Number(p.rulesVersion)||0;if(prior>=314.5)return;ensureKnowledgeState(p);const social=prior<314.4?({GUERREIRO:['Intimidação'],MAGO:['Mentalismo'],LADRAO:['Malandragem']}[p.classKey]||[]):[],classFeatures={GUERREIRO:['Luta Armada'],MAGO:['Meditação','Treino Mágico','Controle Arcano'],LADRAO:['Artes Ladinas','Malabarismo']}[p.classKey]||[],grants=[...social,...classFeatures];for(const name of grants){const clean=normalizeKnowledgeName(name),key=knowledgeKey(clean);if(!p.knowledges[key]||Number(p.knowledges[key].value)<=0)p.knowledges[key]={name:clean,value:1};}const spentLegacyMagePower=!!p.specialUsed?.mage,legacyMageAccess=p.classKey==='MAGO'||!!p.unlockedPowers?.mage;if(legacyMageAccess&&!spentLegacyMagePower){if(!Array.isArray(p.items))p.items=[];const rewindKey=itemMeta('!Voltar no Tempo(Feitiço)').key;if(!p.items.some(raw=>itemMeta(raw).key===rewindKey))p.items.push('!Voltar no Tempo(Feitiço)');}if(p.specialUsed&&Object.prototype.hasOwnProperty.call(p.specialUsed,'mage'))delete p.specialUsed.mage;if(p.unlockedPowers&&Object.prototype.hasOwnProperty.call(p.unlockedPowers,'mage'))delete p.unlockedPowers.mage;}
  function acquireKnowledge(name){const p=ensurePlayerStats(),clean=normalizeKnowledgeName(name),key=knowledgeKey(clean);if(!p||!clean)return {kind:'invalid',name:clean};if(key===knowledgeKey('Colapso Mental')){p.knowledges={};p.knowledgeBoost=0;p.knowledgeBoostTurns=0;markRuntimeChanged();recordJournal('Perdi minhas Perícias permanentes em um colapso mental.',{kind:'knowledge'});return {kind:'collapse',name:clean};}if(key===knowledgeKey('Amnésia')){const turns=secureDie();p.knowledgeBoost=2;p.knowledgeBoostTurns=turns;markRuntimeChanged();recordJournal(`A Amnésia aguçou minhas Perícias por ${turns} turno${turns===1?'':'s'}.`,{kind:'knowledge'});return {kind:'amnesia',name:clean,turns};}const cap=Math.max(0,Math.floor(Number(p.initialMagic)||0)),total=permanentKnowledgeTotal(p);if(total>=cap)return {kind:'limit',name:clean,cap};const current=p.knowledges[key]||{name:clean,value:0};current.name=current.name||clean;current.value=Math.max(0,Number(current.value)||0)+1;p.knowledges[key]=current;markRuntimeChanged();recordJournal(current.value>1?`Aprimorei ${current.name} para nível ${current.value}.`:`Aprendi ${current.name}.`,{kind:'knowledge'});return {kind:'gain',name:current.name,value:current.value,cap};}
