  const STAT_TOKEN_ALIASES={'APTIDÃO':'APTIDÃO','APTIDAO':'APTIDÃO','FORTUNA':'FORTUNA','SANIDADE':'SANIDADE','VIDA':'VIDA'};
  function normalizeStatToken(stat=''){const raw=String(stat||'').trim().normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase();return STAT_TOKEN_ALIASES[raw]||'';}
  function statKeyFromToken(stat=''){return {APTIDÃO:'skill',FORTUNA:'luck',SANIDADE:'magic',VIDA:'stamina'}[normalizeStatToken(stat)]||null;}
