  const SAMSARA_RULES_VERSION=314.9;
  function classify2d6(rolls,mode='ROLL_UNDER'){
    const a=Math.max(1,Math.min(6,Number(rolls?.[0])||1)),b=Math.max(1,Math.min(6,Number(rolls?.[1])||1)),total=a+b,doubleOne=a===1&&b===1,doubleSix=a===6&&b===6,high=String(mode||'ROLL_UNDER').toUpperCase()==='OPPOSED_HIGH',criticalSuccess=high?doubleSix:doubleOne,criticalFailure=high?doubleOne:doubleSix;
    return {a,b,total,doubleOne,doubleSix,criticalSuccess,criticalFailure,quality:criticalSuccess?'CRITICAL_SUCCESS':criticalFailure?'CRITICAL_FAILURE':'NORMAL',mode:high?'OPPOSED_HIGH':'ROLL_UNDER'};
  }
  function rollUnder2d6(rolls,target){const roll=classify2d6(rolls,'ROLL_UNDER'),success=roll.criticalSuccess||(roll.total<=Math.max(0,Number(target)||0)&&!roll.criticalFailure);return {...roll,success};}
  function resolveOpposedExceptional({heroRoll,foeRoll,verdict='tie',heroPowerfulAllowed=true}={}){
    let next=verdict,event='',damageBonus=0;
    if(heroPowerfulAllowed&&heroRoll?.doubleSix&&foeRoll?.doubleSix)return {verdict:'tie',event:'POWERFUL_BLOW_CLASH',damageBonus:0};
    if(foeRoll?.doubleSix)return {verdict:'foe',event:'POWERFUL_BLOW_ENEMY',damageBonus:0};
    if(heroPowerfulAllowed&&heroRoll?.doubleSix)return {verdict:'hero',event:'POWERFUL_BLOW_HERO',damageBonus:0};
    if(heroRoll?.doubleOne&&foeRoll?.doubleOne)return {verdict:'tie',event:'FUMBLE_BOTH',damageBonus:0};
    if(heroRoll?.doubleOne){event='FUMBLE_HERO';if(verdict==='hero')next='tie';else if(verdict==='tie')next='foe';else damageBonus=1;}
    else if(foeRoll?.doubleOne){event='FUMBLE_ENEMY';if(verdict==='foe')next='tie';else if(verdict==='tie')next='hero';else damageBonus=1;}
    return {verdict:next,event,damageBonus};
  }
