  function serializeTempo(t){if(t.zero)return 'TEMPO{\nZERAR\n}';const head=t.duration!=null?`${t.duration}\n`:'\n';return `TEMPO{${head}${(t.actions||[]).map(canonicalizeStatSyntax).join('\n')}\n}`;}
