  function dynamicContext(combat=null){const p=appState.player||{};const c=combat||appState.combat||null;return {APTIDÃO:Number(p.skill)||0,VIDA:Number(p.stamina)||0,SANIDADE:Number(p.magic)||0,FORTUNA:Number(p.luck)||0,MOEDA:goldCount(),APTIDÃO_INICIAL:Number(p.initialSkill)||Number(p.skill)||0,VIDA_INICIAL:Number(p.initialStamina)||Number(p.stamina)||0,SANIDADE_INICIAL:Number(p.initialMagic)||Number(p.magic)||0,FORTUNA_INICIAL:Number(p.initialLuck)||Number(p.luck)||0,OPONENTE_NOME:c?.name||'',OPONENTE_APTIDÃO:Number(c?.skill)||0,OPONENTE_VIDA:Number(c?.stamina)||0};}
