  function resolveDynamicExpression(expr,combat=null,{allowText=false}={}){const raw=String(expr??'').trim();if(!raw)return allowText?'':0;if(/^@OPONENTE\.NOME$/i.test(raw))return String(resolveDynamicToken(raw,combat));const replaced=raw.replace(/@(?:HER[ÓO]I\.)?(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA|MOEDA)(?:\.INICIAL)?|@OPONENTE\.(?:APTIDÃO|APTIDAO|VIDA)/gi,m=>{const v=resolveDynamicToken(m,combat);return Number.isFinite(Number(v))?String(Number(v)):'0';});if(!/^[\d+\-*/().\s]+$/.test(replaced))return allowText?raw:NaN;try{const value=Function(`"use strict";return (${replaced})`)();return Number.isFinite(Number(value))?Number(value):(allowText?raw:NaN);}catch{return allowText?raw:NaN;}}
